"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[811],{83395:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>r,default:()=>l,frontMatter:()=>o,metadata:()=>s,toc:()=>m});const s=JSON.parse('{"id":"async/basic-event-loop","title":"Basic Event Loop Implementation","description":"An event loop is a design pattern in which events are dispatched and/or waited","source":"@site/versioned_docs/version-0.12/05-async/06-basic-event-loop.md","sourceDirName":"05-async","slug":"/async/basic-event-loop","permalink":"/zig.guide/0.12/async/basic-event-loop","draft":false,"unlisted":false,"editUrl":"https://github.com/georg95/zig.guide/tree/master/website/versioned_docs/version-0.12/05-async/06-basic-event-loop.md","tags":[],"version":"0.12","lastUpdatedBy":"Sobeston","lastUpdatedAt":1709417812000,"sidebarPosition":6,"frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"Async Frames, Suspend Blocks","permalink":"/zig.guide/0.12/async/frames-suspend"}}');var i=t(74848),a=t(28453);const o={},r="Basic Event Loop Implementation",d={},m=[];function c(e){const n={code:"code",h1:"h1",header:"header",p:"p",pre:"pre",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"basic-event-loop-implementation",children:"Basic Event Loop Implementation"})}),"\n",(0,i.jsx)(n.p,{children:"An event loop is a design pattern in which events are dispatched and/or waited\nupon. This will mean some kind of service or runtime that resumes suspended\nasync frames when conditions are met. This is the most powerful and useful use\ncase of Zig's async."}),"\n",(0,i.jsx)(n.p,{children:"Here we will implement a basic event loop. This one will allow us to submit\ntasks to be executed in a given amount of time. We will use this to submit pairs\nof tasks which will print the time since the program's start. Here is an example\nof the output."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"[task-pair b] it is now 499 ms since start!\n[task-pair a] it is now 1000 ms since start!\n[task-pair b] it is now 1819 ms since start!\n[task-pair a] it is now 2201 ms since start!\n"})}),"\n",(0,i.jsx)(n.p,{children:"Here is the implementation."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-zig",children:'const std = @import("std");\n\n// used to get monotonic time, as opposed to wall-clock time\nvar timer: ?std.time.Timer = null;\nfn nanotime() u64 {\n    if (timer == null) {\n        timer = std.time.Timer.start() catch unreachable;\n    }\n    return timer.?.read();\n}\n\n// holds the frame, and the nanotime of\n// when the frame should be resumed\nconst Delay = struct {\n    frame: anyframe,\n    expires: u64,\n};\n\n// suspend the caller, to be resumed later by the event loop\nfn waitForTime(time_ms: u64) void {\n    suspend timer_queue.add(Delay{\n        .frame = @frame(),\n        .expires = nanotime() + (time_ms * std.time.ns_per_ms),\n    }) catch unreachable;\n}\n\nfn waitUntilAndPrint(\n    time1: u64,\n    time2: u64,\n    name: []const u8,\n) void {\n    const start = nanotime();\n\n    // suspend self, to be woken up when time1 has passed\n    waitForTime(time1);\n    std.debug.print(\n        "[{s}] it is now {} ms since start!\\n",\n        .{ name, (nanotime() - start) / std.time.ns_per_ms },\n    );\n\n    // suspend self, to be woken up when time2 has passed\n    waitForTime(time2);\n    std.debug.print(\n        "[{s}] it is now {} ms since start!\\n",\n        .{ name, (nanotime() - start) / std.time.ns_per_ms },\n    );\n}\n\nfn asyncMain() void {\n    // stores the async frames of our tasks\n    var tasks = [_]@Frame(waitUntilAndPrint){\n        async waitUntilAndPrint(1000, 1200, "task-pair a"),\n        async waitUntilAndPrint(500, 1300, "task-pair b"),\n    };\n    // |*t| is used, as |t| would be a *const @Frame(...)\n    // which cannot be awaited upon\n    for (tasks) |*t| await t;\n}\n\n// priority queue of tasks\n// lower .expires => higher priority => to be executed before\nvar timer_queue: std.PriorityQueue(Delay, void, cmp) = undefined;\nfn cmp(context: void, a: Delay, b: Delay) std.math.Order {\n    _ = context;\n    return std.math.order(a.expires, b.expires);\n}\n\npub fn main() !void {\n    timer_queue = std.PriorityQueue(Delay, void, cmp).init(\n        std.heap.page_allocator, undefined\n    );\n    defer timer_queue.deinit();\n\n    var main_task = async asyncMain();\n\n    // the body of the event loop\n    // pops the task which is to be next executed\n    while (timer_queue.removeOrNull()) |delay| {\n        // wait until it is time to execute next task\n        const now = nanotime();\n        if (now < delay.expires) {\n            std.time.sleep(delay.expires - now);\n        }\n        // execute next task\n        resume delay.frame;\n    }\n\n    nosuspend await main_task;\n}\n'})})]})}function l(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453:(e,n,t)=>{t.d(n,{R:()=>o,x:()=>r});var s=t(96540);const i={},a=s.createContext(i);function o(e){const n=s.useContext(a);return s.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),s.createElement(a.Provider,{value:n},e.children)}}}]);